:root {
  --color-bg: #e8dcc8;
  --color-border: #7a5c3a;
  --color-header-bg: #7a5c3a;
  --color-header-text: #f5ead8;
  --color-label: #a06830;
  --color-title: #2e1a08;
  --color-field: #7a5c3a;
  --color-value: #2e1a08;
  --color-footer-bg: #d4c0a0;
  --color-footer-text: #7a5c3a;
  --color-divider: #b8985e;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
}

.paddle-tag {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 6px;
  width: 300px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--color-header-bg);
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tag-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--color-label);
}

.tag-title {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-header-text);
  margin: 0;
  line-height: 1.2;
}

.tag-body {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tag-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dashed var(--color-divider);
  padding-bottom: 8px;
}

.tag-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.tag-field {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--color-field);
}

.tag-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-value);
}

.tag-footer {
  background-color: var(--color-footer-bg);
  padding: 8px 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--color-divider);
}

.tag-maker {
  font-size: 11px;
  font-style: italic;
  color: var(--color-footer-text);
}

.tag-date {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-footer-text);
}
